urllib3.util.ssl_.is_ipaddress:
def is_ipaddress(hostname):
    """Detects whether the hostname given is an IPv4 or IPv6 address.
    Also detects IPv6 addresses with Zone IDs.

    :param str hostname: Hostname to examine.
    :return: True if the hostname is an IP address, False otherwise.
    """
    if (not six.PY2 and isinstance(hostname, bytes)):
        hostname = hostname.decode('ascii')
    return bool((IPV4_RE.match(hostname) or BRACELESS_IPV6_ADDRZ_RE.match(hostname)))

urllib3.util.ssl_.resolve_ssl_version:
def resolve_ssl_version(candidate):
    """
    like resolve_cert_reqs
    """
    if candidate is None:
        return PROTOCOL_TLS
    if isinstance(candidate, str):
        res = getattr(ssl, candidate, None)
        if res is None:
            res = getattr(ssl, 'PROTOCOL_' + candidate)
        return res
    return candidate

urllib3.util.ssl_._ssl_wrap_socket_impl:
def _ssl_wrap_socket_impl(sock, ssl_context, tls_in_tls, server_hostname=None):
    if tls_in_tls:
        if not SSLTransport:
            raise ProxySchemeUnsupported("TLS in TLS requires support for the 'ssl' module")
        SSLTransport._validate_ssl_context_for_tls_in_tls(ssl_context)
        return SSLTransport(sock, ssl_context, server_hostname)
    if server_hostname:
        return ssl_context.wrap_socket(sock, server_hostname=server_hostname)
    else:
        return ssl_context.wrap_socket(sock)

urllib3.util.ssl_._is_key_file_encrypted:
def _is_key_file_encrypted(key_file):
    """Detects if a key file is encrypted or not."""
    with open(key_file, 'r') as f:
        for line in f:
            if 'ENCRYPTED' in line:
                return True
    return False

idna.core.valid_contexto:
def valid_contexto(label: str, pos: int, exception: bool = False) -> bool:
    cp_value = ord(label[pos])
    if cp_value == 183:
        if 0 < pos < len(label) - 1:
            if (ord(label[pos - 1]) == 108 and ord(label[pos + 1]) == 108):
                return True
        return False
    elif cp_value == 885:
        if (pos < len(label) - 1 and len(label) > 1):
            return _is_script(label[pos + 1], 'Greek')
        return False
    elif (cp_value == 1523 or cp_value == 1524):
        if pos > 0:
            return _is_script(label[pos - 1], 'Hebrew')
        return False
    elif cp_value == 12539:
        for cp in label:
            if cp == '・':
                continue
            if (_is_script(cp, 'Hiragana') or _is_script(cp, 'Katakana') or _is_script(cp, 'Han')):
                return True
        return False
    elif 1632 <= cp_value <= 1641:
        for cp in label:
            if 1776 <= ord(cp) <= 1785:
                return False
        return True
    elif 1776 <= cp_value <= 1785:
        for cp in label:
            if 1632 <= ord(cp) <= 1641:
                return False
        return True
    return False

idna.core.check_label:
def check_label(label: Union[(str, bytes, bytearray)]) -> None:
    if isinstance(label, (bytes, bytearray)):
        label = label.decode('utf-8')
    if len(label) == 0:
        raise IDNAError('Empty Label')
    check_nfc(label)
    check_hyphen_ok(label)
    check_initial_combiner(label)
    for (pos, cp) in enumerate(label):
        cp_value = ord(cp)
        if intranges_contain(cp_value, idnadata.codepoint_classes['PVALID']):
            continue
        elif intranges_contain(cp_value, idnadata.codepoint_classes['CONTEXTJ']):
            try:
                if not valid_contextj(label, pos):
                    raise InvalidCodepointContext('Joiner {} not allowed at position {} in {}'.format(_unot(cp_value), pos + 1, repr(label)))
            except ValueError:
                raise IDNAError('Unknown codepoint adjacent to joiner {} at position {} in {}'.format(_unot(cp_value), pos + 1, repr(label)))
        elif intranges_contain(cp_value, idnadata.codepoint_classes['CONTEXTO']):
            if not valid_contexto(label, pos):
                raise InvalidCodepointContext('Codepoint {} not allowed at position {} in {}'.format(_unot(cp_value), pos + 1, repr(label)))
        else:
            raise InvalidCodepoint('Codepoint {} at position {} of {} not allowed'.format(_unot(cp_value), pos + 1, repr(label)))
    check_bidi(label)

idna.intranges.intranges_contain:
def intranges_contain(int_: int, ranges: Tuple[(int, ...)]) -> bool:
    """Determine if `int_` falls into one of the ranges in `ranges`."""
    tuple_ = _encode_range(int_, 0)
    pos = bisect.bisect_left(ranges, tuple_)
    if pos > 0:
        (left, right) = _decode_range(ranges[pos - 1])
        if left <= int_ < right:
            return True
    if pos < len(ranges):
        (left, _) = _decode_range(ranges[pos])
        if left == int_:
            return True
    return False

idna.core.check_initial_combiner:
def check_initial_combiner(label: str) -> bool:
    if unicodedata.category(label[0])[0] == 'M':
        raise IDNAError('Label begins with an illegal combining character')
    return True

idna.core.check_hyphen_ok:
def check_hyphen_ok(label: str) -> bool:
    if label[2:4] == '--':
        raise IDNAError('Label has disallowed hyphens in 3rd and 4th position')
    if (label[0] == '-' or label[-1] == '-'):
        raise IDNAError('Label must not start or end with a hyphen')
    return True

idna.core.alabel:
def alabel(label: str) -> bytes:
    try:
        label_bytes = label.encode('ascii')
        ulabel(label_bytes)
        if not valid_label_length(label_bytes):
            raise IDNAError('Label too long')
        return label_bytes
    except UnicodeEncodeError:
        pass
    if not label:
        raise IDNAError('No Input')
    label = str(label)
    check_label(label)
    label_bytes = _punycode(label)
    label_bytes = _alabel_prefix + label_bytes
    if not valid_label_length(label_bytes):
        raise IDNAError('Label too long')
    return label_bytes

idna.core.valid_label_length:
def valid_label_length(label: Union[(bytes, str)]) -> bool:
    if len(label) > 63:
        return False
    return True
